class CaptureBroadcaster extends Illuminate\Broadcasting\Broadcasters\Broadcaster
{
    public function auth($request)
    {
        return $this->verifyUserCanAccessChannel($request, $request->input('channel_name'));
    }

    public function validAuthenticationResponse($request, $result)
    {
        return $result;
    }

    public function broadcast(array $channels, $event, array $payload = [])
    {
        app('cache')->put('broadcast-payload', $payload);
        app('cache')->increment('broadcast-count');
    }
}
config(['broadcasting.default' => 'capture', 'broadcasting.connections.capture' => ['driver' => 'capture']]);
app(Illuminate\Broadcasting\BroadcastManager::class)->extend('capture', fn () => new CaptureBroadcaster());
class QueuedUpdate implements Illuminate\Contracts\Broadcasting\ShouldBroadcast
{
    public function broadcastOn(): array
    {
        return [new Illuminate\Broadcasting\Channel('updates')];
    }
}
class ImmediateUpdate implements Illuminate\Contracts\Broadcasting\ShouldBroadcastNow
{
    public function broadcastOn(): array
    {
        return [new Illuminate\Broadcasting\Channel('updates')];
    }
}
event(new QueuedUpdate());
event(new ImmediateUpdate());
